{
  "questions": [
    {
      "question_id": "q1",
      "question": "What is the physical state of the sample at the intended measurement point?"
    },
    {
      "question_id": "q2",
      "question": "How far is the intended measurement point from where an analyzer could stand?"
    },
    {
      "question_id": "q3",
      "question": "If liquid is present at the measurement point, what does it look like?"
    },
    {
      "question_id": "q4",
      "question": "Is a reference method available that provides comparison values for tumor boundary assessment?"
    },
    {
      "question_id": "q5",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit?"
    },
    {
      "question_id": "q6",
      "question": "Over what range must the target variable for tumor boundary assessment be followed?"
    }
  ],
  "plan": {
    "objective": "Assess whether spectroscopy on retained samples warrants further research for tumor boundary assessment.",
    "samples_and_states": [
      {
        "text": "Use representative retained samples spanning the client-agreed target range and relevant sample states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Obtain matched comparison values for the sampled locations using the reference method agreed with the client.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Record NIR, Raman and UV-Vis spectra at matched sample locations under documented research conditions.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare each candidate with the agreed reference against criteria fixed with the client before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate the candidate approaches on retained material from patients excluded from model development.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Make meeting the pre-agreed criteria, including false-negative outcomes, a condition for proceeding to further research.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Readiness for live surgical tumor boundary decisions would remain unestablished after this retained-sample feasibility study.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify sample states, target range, references and acceptance criteria.",
      "Collect representative retained samples.",
      "Obtain matched reference measurements.",
      "Set up and compare candidate methods at matched locations.",
      "Validate on independent retained material.",
      "Decide go or no-go for further research only."
    ]
  },
  "decision_basis": [
    {
      "text": "Use comparison against the agreed reference on independent retained material and client-agreed criteria to decide whether any candidate merits further research, not clinical deployment.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
